t = int(input())
for _ in range(t):
	(n, k) = map(int, input().split())
	s = input()
	zs = [0]
	os = [0]
	for c in s:
		if c == '1':
			zs.append(zs[-1])
			os.append(os[-1] + 1)
		else:
			zs.append(zs[-1] + 1)
			os.append(os[-1])
	tzs = zs[-1]
	tos = os[-1]
	zr = []
	ol = []
	for i in range(n):
		if s[i] == '1':
			v = tzs - zs[i + 1]
			if v == 0:
				break
			else:
				zr.append(v)
	for i in range(n - 1, -1, -1):
		if s[i] == '0':
			v = os[i + 1]
			if v == 0:
				break
			else:
				ol.append(v)
	if k >= len(zr) or k >= len(ol):
		print(0)
		continue
	a1 = [0]
	for kk in zr:
		a1.append(a1[-1] + kk)
	a2 = [0]
	for kk in ol:
		a2.append(a2[-1] + kk)
	mv = float('inf')
	diff = sum(zr)
	for i in range(k + 1):
		j = k - i
		mv = min(mv, diff - a1[i] - a2[j] + i * j)
	print(max(0, mv))
